#[derive(Clone, Copy, Debug)]
enum DraweropenerStep {
    Start,
    OnInit,
    OnEnable,
    OnTimer1000,
    OnTimer4500,
}

fn draweropener_run(ctx: &Ctx, mut step: DraweropenerStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            DraweropenerStep::Start => {
                step = DraweropenerStep::OnInit;
                continue 'machine;
            }
            DraweropenerStep::OnInit => {
                ctx.call(Function::DisableNpc, vec![Val::from("#DrawerOpener")])?;
                return Err(Stop::End);
            }
            DraweropenerStep::OnEnable => {
                ctx.call(Function::EnableNpc, vec![Val::from("#DrawerOpener")])?;
                ctx.call(Function::InitNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            DraweropenerStep::OnTimer1000 => {
                ctx.call(Function::EnableNpc, vec![Val::from("Upper Drawer#Second")])?;
                ctx.call(Function::DisableNpc, vec![Val::from("Upper Drawer#First")])?;
                return Err(Stop::End);
            }
            DraweropenerStep::OnTimer4500 => {
                ctx.call(Function::EnableNpc, vec![Val::from("Upper Drawer#First")])?;
                ctx.call(Function::DisableNpc, vec![Val::from("Upper Drawer#Second")])?;
                ctx.call(Function::DisableNpc, vec![Val::from("#DrawerOpener")])?;
                ctx.call(Function::StopNpcTimer, vec![])?;
                return Err(Stop::End);
            }
        }
    }
}

pub fn draweropener(ctx: &Ctx) -> Script {
    draweropener_run(ctx, DraweropenerStep::Start, Vec::new()).map(|_| ())
}

pub fn draweropener_oninit(ctx: &Ctx) -> Script {
    draweropener_run(ctx, DraweropenerStep::OnInit, Vec::new()).map(|_| ())
}

pub fn draweropener_onenable(ctx: &Ctx) -> Script {
    draweropener_run(ctx, DraweropenerStep::OnEnable, Vec::new()).map(|_| ())
}

pub fn draweropener_ontimer1000(ctx: &Ctx) -> Script {
    draweropener_run(ctx, DraweropenerStep::OnTimer1000, Vec::new()).map(|_| ())
}

pub fn draweropener_ontimer4500(ctx: &Ctx) -> Script {
    draweropener_run(ctx, DraweropenerStep::OnTimer4500, Vec::new()).map(|_| ())
}

