#[derive(Clone, Copy, Debug)]
enum HumspawnerStep {
    Start,
    OnMonster,
    OnTimer60000,
    OnMonsterDead,
}

fn humspawner_run(ctx: &Ctx, mut step: HumspawnerStep, args: Vec<Val>) -> Result<Val, Stop> {
    'machine: loop {
        match step {
            HumspawnerStep::Start => {
                step = HumspawnerStep::OnMonster;
                continue 'machine;
            }
            HumspawnerStep::OnMonster => {
                if ctx.call(Function::Rand, vec![Val::from(0), Val::from(1)])?.is_true() {
                    ctx.call(
                        Function::MapAnnounce,
                        vec![
                            Val::from("lhz_in01"),
                            Val::from("Intruder alert! Protect the research documents!"),
                            Val::from(1),
                            Val::from(16711680),
                        ],
                    )?;
                } else {
                    ctx.call(
                        Function::MapAnnounce,
                        vec![
                            Val::from("lhz_in01"),
                            Val::from("Intruder alert! Intruder alert!"),
                            Val::from(1),
                            Val::from(16711680),
                        ],
                    )?;
                }
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("lhz_in01"),
                        Val::from(208),
                        Val::from(133),
                        Val::from("Guard"),
                        Val::from(1682),
                        Val::from(1),
                        Val::from("HuMSpawner::OnMonsterDead"),
                    ],
                )?;
                ctx.call(
                    Function::Monster,
                    vec![
                        Val::from("lhz_in01"),
                        Val::from(217),
                        Val::from(135),
                        Val::from("Guard"),
                        Val::from(1682),
                        Val::from(1),
                        Val::from("HuMSpawner::OnMonsterDead"),
                    ],
                )?;
                ctx.call(Function::InitNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            HumspawnerStep::OnTimer60000 => {
                ctx.call(
                    Function::KillMonster,
                    vec![Val::from("lhz_in01"), Val::from("HuMSpawner::OnMonsterDead")],
                )?;
                ctx.call(Function::StopNpcTimer, vec![])?;
                return Err(Stop::End);
            }
            HumspawnerStep::OnMonsterDead => {
                return Err(Stop::End);
            }
        }
    }
}

pub fn humspawner(ctx: &Ctx) -> Script {
    humspawner_run(ctx, HumspawnerStep::Start, Vec::new()).map(|_| ())
}

